// 1. 페치 조인 — JPQL 에 쓴다
List<Order> orders = em.createQuery(
        "select o from Order o join fetch o.member", Order.class)
        .getResultList();

// 2. @EntityGraph — 7장에서 이렇게 쓴다
@EntityGraph(attributePaths = {"member"})
List<Order> findAll();

// 3. 배치 사이즈 — 설정 한 줄
